class Solution {
    fun reverseOddLevels(root:TreeNode?):TreeNode?{
        val queue=java.util.ArrayDeque<TreeNode>();
        queue.add(root!!);
        var level=0;
        while(queue.isNotEmpty()){
            val nodes=mutableListOf<TreeNode>();
            repeat(queue.size){
                val node=queue.removeFirst();
                nodes.add(node);
                if(node.left!=null){
                    queue.add(node.left!!);
                    queue.add(node.right!!)
                }
            };
            if(level%2==1){
                var left=0;
                var right=nodes.lastIndex;
                while(left<right){
                    val value=nodes[left].`val`;
                    nodes[left].`val`=nodes[right].`val`;
                    nodes[right].`val`=value;
                    left++;
                    right--
                }
            };
            level++
        };
        return root
    }
}

